import { useAuth } from "@/_core/hooks/useAuth";
import { ResumeDocument } from "@/components/resume/ResumeDocument";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Slider } from "@/components/ui/slider";
import { Textarea } from "@/components/ui/textarea";
import { trpc } from "@/lib/trpc";
import { downloadResumePdf } from "@/lib/resumePdf";
import { RESUME_TEMPLATES, newResumeData, normalizeResumeData, sampleResumeData, type Experience, type ResumeData, type ResumeSectionKey, type ResumeTemplateId } from "@shared/resume";
import { AlignLeft, ArrowDownUp, ArrowLeft, Bold, ChevronDown, ChevronUp, CircleCheck, Copy, Download, Eye, FileText, FileUp, GripVertical, ImagePlus, Italic, History as HistoryIcon, LayoutTemplate, List, ListOrdered, Loader2, PanelLeft, Plus, Printer, RemoveFormatting, Redo2, RotateCcw, Save, Settings2, Sparkles, Trash2, Undo2, WandSparkles, X } from "lucide-react";
import { ChangeEvent, useEffect, useId, useMemo, useRef, useState } from "react";
import { toast } from "sonner";
import { Link, useLocation, useRoute } from "wouter";

const sectionInfo: { key: ResumeSectionKey; label: string; description: string }[] = [
  { key: "summary", label: "Summary", description: "Your professional point of view" }, { key: "experience", label: "Experience", description: "Work history and impact" }, { key: "education", label: "Education", description: "Learning and qualifications" }, { key: "skills", label: "Skills", description: "Your strongest tools" }, { key: "projects", label: "Projects", description: "Work worth showing" }, { key: "certifications", label: "Certifications", description: "Credentials and training" }, { key: "languages", label: "Languages", description: "Language proficiency" }, { key: "awards", label: "Awards", description: "Recognition and wins" }, { key: "volunteer", label: "Volunteer", description: "Community experience" }, { key: "interests", label: "Interests", description: "A little more about you" },
];

const makeId = () => (globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random()}`);
// Unsaved work on /editor/new survives sign-in, navigation and refreshes.
const DRAFT_STORAGE_KEY = "cv-studio:unsaved-draft";
const clearStoredDraft = () => { try { window.localStorage.removeItem(DRAFT_STORAGE_KEY); } catch { /* storage unavailable */ } };
// Identifies the persisted state so autosave only fires for real changes.
const snapshotKey = (value: { title?: string; template?: string; data?: unknown }) => JSON.stringify([value.title, value.template, value.data]);
const emptyExperience = (): Experience => ({ id: makeId(), role: "", company: "", location: "", start: "", end: "", current: false, description: "", highlights: [] });
type RevisionSnapshot = { id: string; name: string; title: string; template: ResumeTemplateId; data: ResumeData; createdAt: string; kind?: "manual" | "automatic" };

export default function Editor() {
  const [, params] = useRoute("/editor/:id");
  const [, setLocation] = useLocation();
  const url = new URL(window.location.href);
  const requestedId = params?.id ?? "new";
  const requestedTemplate = (url.searchParams.get("template") ?? "modern") as ResumeTemplateId;
  const numericId = requestedId === "new" ? undefined : Number(requestedId);
  const { isAuthenticated, loading: authLoading } = useAuth();
  const utils = trpc.useUtils();
  const { data: savedResume, isLoading: resumeLoading, error: resumeError } = trpc.resume.get.useQuery({ id: numericId ?? 1 }, { enabled: Boolean(numericId) });
  const { data: photos } = trpc.photo.list.useQuery(undefined, { enabled: isAuthenticated });
  const [title, setTitle] = useState("Untitled resume");
  const [template, setTemplate] = useState<ResumeTemplateId>(RESUME_TEMPLATES.some((item) => item.id === requestedTemplate) ? requestedTemplate : "modern");
  const [data, setData] = useState<ResumeData>(() => newResumeData(template));
  const [selected, setSelected] = useState<"personal" | ResumeSectionKey>("personal");
  const [zoom, setZoom] = useState(68);
  const [showStyle, setShowStyle] = useState(false);
  const [showRevisions, setShowRevisions] = useState(false);
  const [revisionName, setRevisionName] = useState("");
  const [revisions, setRevisions] = useState<RevisionSnapshot[]>([]);
  const [downloadingPdf, setDownloadingPdf] = useState(false);
  const [started, setStarted] = useState(Boolean(numericId));
  const [savedAt, setSavedAt] = useState<Date | null>(null);
  const [history, setHistory] = useState<ResumeData[]>([]);
  const [future, setFuture] = useState<ResumeData[]>([]);
  const [importedFrom, setImportedFrom] = useState<string | null>(null);
  const hydrated = useRef(false);
  const hydratedId = useRef<number | null>(null);
  const lastSaved = useRef<string | null>(null);
  const saveTimer = useRef<number | undefined>(undefined);
  const latest = useRef({ title, template, data });
  latest.current = { title, template, data };
  const create = trpc.resume.create.useMutation({ onSuccess: (resume, saved) => { lastSaved.current = snapshotKey(saved); clearStoredDraft(); setSavedAt(new Date()); utils.resume.list.invalidate(); setLocation(`/editor/${resume.id}`); toast.success("Resume saved to your dashboard"); }, onError: () => toast.error("We could not save your resume. Please try again.") });
  const update = trpc.resume.update.useMutation({ onSuccess: (_resume, saved) => { lastSaved.current = snapshotKey(saved); setSavedAt(new Date()); utils.resume.list.invalidate(); }, onError: () => toast.error("Autosave paused. Please try again.") });
  const upload = trpc.photo.upload.useMutation({ onSuccess: (photo) => { updateData((draft) => ({ ...draft, photoUrl: photo.url })); utils.photo.list.invalidate(); toast.success("Headshot added to your resume"); }, onError: (error) => toast.error(error.message || "Unable to upload image. Please try again.") });
  const importResume = trpc.resume.import.useMutation({ onSuccess: (result) => { setData(normalizeResumeData(result.data, template)); setTitle(result.fileName.replace(/\.(pdf|docx)$/i, "") || "Imported resume"); setStarted(true); setSelected("personal"); setImportedFrom(result.fileName); toast.success("Your resume is ready to edit"); }, onError: (error) => toast.error(error.message || "We could not import that resume.") });

  useEffect(() => { if (savedResume && hydratedId.current !== savedResume.id) { const loaded = normalizeResumeData(savedResume.data, savedResume.template as ResumeTemplateId); hydratedId.current = savedResume.id; lastSaved.current = snapshotKey({ title: savedResume.title, template: savedResume.template, data: loaded }); setTitle(savedResume.title); setTemplate(savedResume.template as ResumeTemplateId); setData(loaded); setStarted(true); hydrated.current = true; setSavedAt(new Date(savedResume.updatedAt)); } }, [savedResume]);
  useEffect(() => { if (!numericId) hydrated.current = true; }, [numericId]);
  useEffect(() => () => { if (saveTimer.current) window.clearTimeout(saveTimer.current); }, []);
  useEffect(() => { if (!numericId || !hydrated.current || !isAuthenticated || snapshotKey({ title, template, data }) === lastSaved.current) return; if (saveTimer.current) window.clearTimeout(saveTimer.current); saveTimer.current = window.setTimeout(() => { const next = latest.current; update.mutate({ id: numericId, title: next.title, template: next.template, data: next.data }); }, 850); return () => { if (saveTimer.current) window.clearTimeout(saveTimer.current); }; }, [data, title, template, numericId, isAuthenticated]);
  useEffect(() => { if (url.searchParams.get("print") === "true" && savedResume && !resumeLoading) window.setTimeout(() => printResume(), 400); }, [savedResume, resumeLoading]);
  useEffect(() => { if (numericId || url.searchParams.get("import") === "true") return; try { const raw = window.localStorage.getItem(DRAFT_STORAGE_KEY); if (!raw) return; const draft = JSON.parse(raw) as { title?: string; template?: string; data?: unknown }; const restoredTemplate = RESUME_TEMPLATES.find((item) => item.id === draft.template)?.id ?? template; setTemplate(restoredTemplate); setData(normalizeResumeData(draft.data, restoredTemplate)); setTitle(draft.title || "Untitled resume"); setStarted(true); toast.message("We restored your unsaved draft.", { action: { label: "Start over", onClick: () => { clearStoredDraft(); setData(newResumeData(restoredTemplate)); setTitle("Untitled resume"); setHistory([]); setFuture([]); setStarted(false); } } }); } catch { clearStoredDraft(); } }, []);
  useEffect(() => { if (numericId || !started) return; const timer = window.setTimeout(() => { try { window.localStorage.setItem(DRAFT_STORAGE_KEY, JSON.stringify(latest.current)); } catch { /* storage full or unavailable */ } }, 400); return () => window.clearTimeout(timer); }, [numericId, started, title, template, data]);
  const revisionStorageKey = `cv-studio:resume-revisions:${requestedId}`;
  useEffect(() => { try { const raw = window.localStorage.getItem(revisionStorageKey); setRevisions(raw ? JSON.parse(raw) as RevisionSnapshot[] : []); } catch { setRevisions([]); } }, [revisionStorageKey]);
  function persistRevisions(next: RevisionSnapshot[]) { setRevisions(next); try { window.localStorage.setItem(revisionStorageKey, JSON.stringify(next)); } catch { toast.error("Revision history could not be saved on this device."); } }
  function saveRevision() { const name = revisionName.trim() || `${title || "Resume"} · ${new Date().toLocaleDateString()}`; const snapshot: RevisionSnapshot = { id: makeId(), name, title, template, data: JSON.parse(JSON.stringify(data)) as ResumeData, createdAt: new Date().toISOString(), kind: "manual" }; persistRevisions([snapshot, ...revisions].slice(0, 30)); setRevisionName(""); toast.success("Resume version saved"); }
  function createAutomaticSnapshot(reason: string) { const current = latest.current; const fingerprint = JSON.stringify({ title: current.title, template: current.template, data: current.data }); const newest = revisions[0]; if (newest && JSON.stringify({ title: newest.title, template: newest.template, data: newest.data }) === fingerprint) return; const snapshot: RevisionSnapshot = { id: makeId(), name: `Automatic · Before ${reason}`, title: current.title, template: current.template, data: JSON.parse(JSON.stringify(current.data)) as ResumeData, createdAt: new Date().toISOString(), kind: "automatic" }; persistRevisions([snapshot, ...revisions].slice(0, 30)); }
  function restoreRevision(snapshot: RevisionSnapshot) { createAutomaticSnapshot("restoring another version"); setHistory((stack) => [...stack.slice(-29), data]); setFuture([]); setTitle(snapshot.title); setTemplate(snapshot.template); setData(normalizeResumeData(snapshot.data, snapshot.template)); setShowRevisions(false); toast.success(`Restored “${snapshot.name}”`); }
  function deleteRevision(id: string) { persistRevisions(revisions.filter((snapshot) => snapshot.id !== id)); toast.success("Version removed"); }


  const completion = useMemo(() => { const checks = [data.fullName, data.professionalTitle, data.email, data.summary, data.experiences.length, data.education.length, data.skills.length].filter(Boolean).length; return Math.round((checks / 7) * 100); }, [data]);
  const score = useMemo(() => { let points = 28; if (data.fullName && data.email && data.phone) points += 18; if (data.summary.length > 60) points += 14; if (data.experiences.length) points += 16; if (data.education.length) points += 10; if (data.skills.length >= 3) points += 10; if (data.experiences.some((item) => /\d|%|\$/.test(`${item.description} ${item.highlights.join(" ")}`))) points += 4; return Math.min(points, 100); }, [data]);
  function updateData(next: (current: ResumeData) => ResumeData) { setData((current) => { const result = next(current); setHistory((stack) => [...stack.slice(-29), current]); setFuture([]); return result; }); }
  function doUndo() { const previous = history.at(-1); if (!previous) return; setHistory((stack) => stack.slice(0, -1)); setFuture((stack) => [data, ...stack].slice(0, 30)); setData(previous); }
  function doRedo() { const next = future[0]; if (!next) return; setFuture((stack) => stack.slice(1)); setHistory((stack) => [...stack, data].slice(-30)); setData(next); }
  async function saveNow() { if (!isAuthenticated) { try { window.localStorage.setItem(DRAFT_STORAGE_KEY, JSON.stringify(latest.current)); } catch { /* storage full or unavailable */ } toast.message("Sign in to save — your draft will be waiting for you."); setLocation(`/login?next=${encodeURIComponent("/editor/new")}`); return; } let next = latest.current; if (next.data.photoUrl.startsWith("data:")) { try { const photo = await upload.mutateAsync({ fileName: "headshot", dataUrl: next.data.photoUrl }); next = { ...next, data: { ...next.data, photoUrl: photo.url } }; } catch { return; } } if (numericId) update.mutate({ id: numericId, title: next.title, template: next.template, data: next.data }); else create.mutate({ title: next.title, template: next.template, data: next.data }); }
  function printResume() { const originalTitle = document.title; document.title = `${(title || data.fullName || "Resume").replace(/[^a-z0-9]+/gi, "_")}_CV`; window.print(); window.setTimeout(() => { document.title = originalTitle; }, 500); }
  function downloadPdf() { try { setDownloadingPdf(true); downloadResumePdf({ data, title, template }); toast.success("Your PDF download has started."); } catch { toast.error("Your resume could not be downloaded. Please try again."); } finally { window.setTimeout(() => setDownloadingPdf(false), 350); } }
  function moveSection(key: ResumeSectionKey, direction: -1 | 1) { createAutomaticSnapshot("reordering sections"); updateData((draft) => { const index = draft.sectionOrder.indexOf(key); const destination = index + direction; if (destination < 0 || destination >= draft.sectionOrder.length) return draft; const order = [...draft.sectionOrder]; [order[index], order[destination]] = [order[destination], order[index]]; return { ...draft, sectionOrder: order }; }); }
  function toggleSection(key: ResumeSectionKey) { createAutomaticSnapshot("changing section visibility"); updateData((draft) => ({ ...draft, hiddenSections: draft.hiddenSections.includes(key) ? draft.hiddenSections.filter((item) => item !== key) : [...draft.hiddenSections, key] })); }
  function handleUpload(event: ChangeEvent<HTMLInputElement>) { const file = event.target.files?.[0]; if (!file) return; if (!["image/jpeg", "image/png", "image/webp"].includes(file.type) || file.size > 2 * 1024 * 1024) { toast.error("Choose a JPG, PNG, or WebP image smaller than 2 MB."); return; } const reader = new FileReader(); reader.onload = () => { const dataUrl = String(reader.result); if (isAuthenticated) upload.mutate({ fileName: file.name, dataUrl }); else { updateData((draft) => ({ ...draft, photoUrl: dataUrl })); toast.success("Headshot added. Sign in to keep it with your saved resume."); } }; reader.onerror = () => toast.error("We could not read that image."); reader.readAsDataURL(file); event.target.value = ""; }
  function handleImport(event: ChangeEvent<HTMLInputElement>) { const file = event.target.files?.[0]; if (!file) return; const validType = ["application/pdf", "application/vnd.openxmlformats-officedocument.wordprocessingml.document"].includes(file.type) || /\.(pdf|docx)$/i.test(file.name); if (!validType || file.size > 8 * 1024 * 1024) { toast.error("Choose a PDF or DOCX resume smaller than 8 MB."); event.target.value = ""; return; } if (started) createAutomaticSnapshot("importing a new resume"); const reader = new FileReader(); reader.onload = () => importResume.mutate({ fileName: file.name, dataUrl: String(reader.result) }); reader.onerror = () => toast.error("We could not read that file."); reader.readAsDataURL(file); event.target.value = ""; }
  if (resumeLoading || authLoading) return <div className="app-loading"><span className="loading-mark"><FileText /></span><p>Opening your editor…</p></div>;
  if (resumeError) return <div className="editor-error"><h1>That resume is unavailable.</h1><p>It may have been removed or you may not have permission to open it.</p><Link href="/dashboard"><Button>Back to my resumes</Button></Link></div>;
  return <div className="editor-shell"><header className="editor-header no-print"><div className="editor-header-left"><Link href={isAuthenticated ? "/dashboard" : "/"} className="editor-back"><ArrowLeft size={17} /><span>Back</span></Link><span className="editor-divider" /><div><Input className="editor-title-input" value={title} onChange={(event) => setTitle(event.target.value)} aria-label="Resume name" /><p>{isAuthenticated ? (update.isPending || create.isPending ? "Saving…" : savedAt ? `Saved ${savedAt.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" })}` : "Not saved yet") : "Local draft — sign in to save"}</p></div></div><div className="editor-header-actions"><button onClick={doUndo} disabled={!history.length} aria-label="Undo"><Undo2 size={17} /></button><button onClick={doRedo} disabled={!future.length} aria-label="Redo"><RotateCcw size={17} /></button><span className="editor-divider" /><button className={`editor-revisions-trigger ${showRevisions ? "active" : ""}`} onClick={() => setShowRevisions((open) => !open)} aria-label="Open resume versions"><HistoryIcon size={17} /><span className="hide-mobile">Versions</span></button><Button variant="outline" onClick={printResume}><Printer size={16} /><span className="hide-mobile">Print</span></Button><Button variant="outline" onClick={downloadPdf} disabled={downloadingPdf}><Download size={16} /><span className="hide-mobile">{downloadingPdf ? "Preparing…" : "Download PDF"}</span></Button><Button onClick={saveNow} disabled={update.isPending || create.isPending}><Save size={16} />{numericId ? "Save" : "Save resume"}</Button></div></header>{showRevisions && <RevisionPanel revisions={revisions} revisionName={revisionName} setRevisionName={setRevisionName} onSave={saveRevision} onRestore={restoreRevision} onDelete={deleteRevision} onClose={() => setShowRevisions(false)} />}{!started ? <NewResumeChoice template={template} importPending={importResume.isPending} onImport={handleImport} onStart={(kind) => { const base = kind === "sample" ? sampleResumeData(template) : newResumeData(template); setData(base); setTitle(kind === "sample" ? "Alex Morgan resume" : "Untitled resume"); setStarted(true); }} onTemplate={(next) => setTemplate(next)} /> : <div className="editor-workspace"><aside className="editor-sidebar no-print"><div className="editor-progress"><div><span>Resume completion</span><strong>{completion}%</strong></div><div className="progress-track"><i style={{ width: `${completion}%` }} /></div></div><button className={`section-nav-item ${selected === "personal" ? "active" : ""}`} onClick={() => setSelected("personal")}><span className="section-dot">{data.fullName && data.email ? <CircleCheck size={15} /> : "1"}</span><span><strong>Personal details</strong><small>Contact information</small></span></button><div className="section-nav-list">{data.sectionOrder.map((key) => { const info = sectionInfo.find((item) => item.key === key)!; const completed = key === "summary" ? data.summary : key === "experience" ? data.experiences.length : key === "education" ? data.education.length : key === "skills" ? data.skills.length : false; return <button className={`section-nav-item ${selected === key ? "active" : ""}`} onClick={() => setSelected(key)} key={key}><span className="section-dot">{completed ? <CircleCheck size={15} /> : ""}</span><span><strong>{info.label}</strong><small>{data.hiddenSections.includes(key) ? "Hidden" : info.description}</small></span></button>; })}</div><div className="editor-sidebar-footer"><button onClick={() => setShowStyle((open) => !open)} className={showStyle ? "active" : ""}><Settings2 size={17} />Style &amp; layout</button><Link href="/templates"><LayoutTemplate size={17} />Templates</Link></div></aside><main className="editor-form-pane no-print">{importedFrom && <div className="import-success-banner"><div><FileUp size={16} /><span><strong>{importedFrom}</strong> is now open in the editor.</span></div><button onClick={() => setImportedFrom(null)} aria-label="Dismiss import notice"><X size={15} /></button></div>}<div className="editor-form-scroll"><EditorForm selected={selected} data={data} setData={updateData} onUpload={handleUpload} uploadPending={upload.isPending} photos={photos ?? []} /></div>{showStyle && <StyleDrawer data={data} setData={updateData} template={template} setTemplate={(next) => { if (next !== template) createAutomaticSnapshot("changing the template"); setTemplate(next); }} onClose={() => setShowStyle(false)} />}</main><aside className="preview-pane"><div className="preview-toolbar no-print"><div><Eye size={16} /><span>Live preview</span></div><div><button onClick={() => setZoom((value) => Math.max(45, value - 5))} aria-label="Zoom out">−</button><span>{zoom}%</span><button onClick={() => setZoom((value) => Math.min(100, value + 5))} aria-label="Zoom in">+</button></div></div><div className="preview-canvas"><div className="resume-zoom" style={{ "--preview-scale": zoom / 100 } as React.CSSProperties}><ResumeDocument data={data} template={template} /></div></div><div className="preview-mobile-action no-print"><Button variant="outline" onClick={printResume}><Printer size={16} />Print</Button><Button onClick={downloadPdf} disabled={downloadingPdf}><Download size={16} />{downloadingPdf ? "Preparing…" : "Download PDF"}</Button></div></aside></div>}</div>;
}

function RevisionPanel({ revisions, revisionName, setRevisionName, onSave, onRestore, onDelete, onClose }: { revisions: RevisionSnapshot[]; revisionName: string; setRevisionName: (value: string) => void; onSave: () => void; onRestore: (snapshot: RevisionSnapshot) => void; onDelete: (id: string) => void; onClose: () => void }) { return <aside className="revision-panel no-print" aria-label="Resume versions"><div className="revision-panel-header"><div><p className="eyebrow">Version control</p><h2>Resume versions</h2></div><button onClick={onClose} aria-label="Close versions"><X size={17} /></button></div><p className="revision-panel-lede">Save a complete draft before making a big change. Versions stay on this device and never alter your current resume until you restore one.</p><div className="revision-save-row"><Input value={revisionName} onChange={(event) => setRevisionName(event.target.value)} placeholder="Name this version" onKeyDown={(event) => { if (event.key === "Enter") onSave(); }} /><Button onClick={onSave}><Save size={15} />Save version</Button></div><div className="revision-list">{revisions.length === 0 ? <div className="revision-empty"><HistoryIcon size={20} /><strong>No saved versions yet</strong><span>Save your first complete draft above.</span></div> : revisions.map((snapshot) => <div className="revision-item" key={snapshot.id}><div><strong>{snapshot.name}</strong>{snapshot.kind === "automatic" && <em>Auto-saved before a major change</em>}<span>{new Date(snapshot.createdAt).toLocaleString([], { dateStyle: "medium", timeStyle: "short" })}</span><small>{snapshot.data.experiences.length} roles · {snapshot.data.projects.length} projects · {snapshot.data.skills.length} skills</small></div><div className="revision-item-actions"><button onClick={() => onRestore(snapshot)} aria-label={`Restore ${snapshot.name}`}>Restore</button><button onClick={() => onDelete(snapshot.id)} aria-label={`Delete ${snapshot.name}`}><Trash2 size={14} /></button></div></div>)}</div></aside>; }

function NewResumeChoice({ template, onTemplate, onStart, onImport, importPending }: { template: ResumeTemplateId; onTemplate: (template: ResumeTemplateId) => void; onStart: (kind: "blank" | "sample") => void; onImport: (event: ChangeEvent<HTMLInputElement>) => void; importPending: boolean }) { return <main className="new-resume-choice"><div className="choice-copy"><p className="eyebrow">A thoughtful first step</p><h1>How would you like<br />to <em>begin?</em></h1><p>Bring in an existing resume and keep editing, or start from a clean page with a polished template.</p><div className="choice-actions"><Button size="lg" onClick={() => onStart("blank")}><PenLineIcon />Start from scratch</Button><Button size="lg" variant="outline" onClick={() => onStart("sample")}><Sparkles size={17} />Start with sample CV</Button><label className="import-choice-button"><FileUp size={17} />{importPending ? "Reading resume…" : "Import PDF or DOCX"}<input type="file" accept="application/pdf,.pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document,.docx" onChange={onImport} disabled={importPending} /></label></div><p className="import-note">PDF and DOCX files up to 8 MB. Your resume opens directly in the full editor with a live preview.</p><Link href="/templates" className="text-link">Browse every template <ArrowLeft size={15} className="rotate-180" /></Link></div><div className="choice-template"><p>Selected template</p><div className="template-selector"><select value={template} onChange={(event) => onTemplate(event.target.value as ResumeTemplateId)} aria-label="Select a template">{RESUME_TEMPLATES.map((item) => <option key={item.id} value={item.id}>{item.name} — {item.category}</option>)}</select></div><div className="choice-preview" data-tilt="5"><ResumeDocument data={sampleResumeData(template)} template={template} /></div></div></main>; }

function ImportReview({ result, onApply, onCancel }: { result: { fileName: string; data: ResumeData; textPreview: string; warnings: string[] }; onApply: () => void; onCancel: () => void }) {
  const sections = [
    { label: "Personal details", items: [result.data.fullName, result.data.professionalTitle, result.data.email, result.data.phone, result.data.location, result.data.website, result.data.linkedin, result.data.github] },
    { label: "Professional summary", items: [result.data.summary] },
    { label: "Experience", items: result.data.experiences.flatMap((item) => [item.role, item.company, [item.start, item.end].filter(Boolean).join(" – "), item.location, item.description, ...item.highlights]) },
    { label: "Education", items: result.data.education.flatMap((item) => [item.qualification, item.institution, [item.start, item.end].filter(Boolean).join(" – "), item.location, item.grade, item.description]) },
    { label: "Skills", items: result.data.skills.map((item) => item.name) },
    { label: "Projects", items: result.data.projects.flatMap((item) => [item.name, item.role, item.description, item.technologies, item.liveDemoUrl, item.githubUrl, item.caseStudyUrl, item.url]) },
    { label: "Certifications", items: result.data.certifications.flatMap((item) => [item.name, item.issuer, item.date, item.credentialUrl]) },
    { label: "Languages", items: result.data.languages.map((item) => `${item.name} · ${item.proficiency}`) },
    { label: "Awards", items: result.data.awards.flatMap((item) => [item.name, item.issuer, item.date, item.description]) },
    { label: "Volunteer", items: result.data.volunteer.flatMap((item) => [item.organization, item.role, [item.start, item.end].filter(Boolean).join(" – "), item.description]) },
    { label: "Interests", items: result.data.interests },
  ].map((section) => ({ ...section, items: section.items.map((item) => String(item ?? "").trim()).filter(Boolean) })).filter((section) => section.items.length);
  const extractedCount = sections.reduce((total, section) => total + section.items.length, 0);
  return <main className="import-review"><div className="import-review-card"><div className="import-review-icon"><FileUp size={22} /></div><p className="eyebrow">Import review</p><h1>We found your resume content.</h1><p className="import-review-lede">We extracted <strong>{extractedCount} fields</strong> from <strong>{result.fileName}</strong>. Check every section below, then apply it to the editor where you can continue correcting and formatting it.</p><div className="import-review-grid"><div><span>Extracted sections</span><strong>{sections.length} sections</strong><div className="import-section-list">{sections.map((section) => <div key={section.label}><span>{section.label}</span><strong>{section.items.length}</strong></div>)}</div></div><div><span>All extracted data</span><div className="import-data-preview">{sections.map((section) => <section key={section.label}><h3>{section.label}</h3><ul>{section.items.map((item, index) => <li key={`${section.label}-${index}`}>{item}</li>)}</ul></section>)}</div></div></div><details className="import-source-details"><summary>View source text sample</summary><p className="import-text-preview">{result.textPreview}</p></details><p className="import-warning">{result.warnings[0]}</p><div className="import-review-actions"><Button variant="outline" onClick={onCancel}>Choose another file</Button><Button onClick={onApply}><CircleCheck size={16} />Apply to editor</Button></div></div></main>;
}

function PenLineIcon() { return <PanelLeft size={17} />; }

function compareExperiences(a: Experience, b: Experience) { const score = (item: Experience) => item.current ? Number.POSITIVE_INFINITY : Number.parseInt((item.start || item.end || "0").match(/\d{4}/)?.[0] ?? "0", 10); return score(b) - score(a); }

function EditorForm({ selected, data, setData, onUpload, uploadPending, photos }: { selected: "personal" | ResumeSectionKey; data: ResumeData; setData: (next: (current: ResumeData) => ResumeData) => void; onUpload: (event: ChangeEvent<HTMLInputElement>) => void; uploadPending: boolean; photos: { id: number; url: string; fileName: string }[] }) {
  const setField = (key: keyof ResumeData, value: any) => setData((draft) => ({ ...draft, [key]: value }));
  const [draggedExperienceId, setDraggedExperienceId] = useState<string | null>(null);
  const [dragOverExperienceId, setDragOverExperienceId] = useState<string | null>(null);
  const moveExperience = (targetId: string) => { if (!draggedExperienceId || draggedExperienceId === targetId) return; setData((draft) => { const next = [...draft.experiences]; const from = next.findIndex((item) => item.id === draggedExperienceId); const to = next.findIndex((item) => item.id === targetId); if (from < 0 || to < 0) return draft; const [moved] = next.splice(from, 1); next.splice(to, 0, moved); return { ...draft, experiences: next, theme: { ...draft.theme, experienceOrderMode: "manual" } }; }); };
  const moveExperienceByOffset = (id: string, offset: number) => setData((draft) => { const next = [...draft.experiences]; const from = next.findIndex((item) => item.id === id); const to = from + offset; if (from < 0 || to < 0 || to >= next.length) return draft; const [moved] = next.splice(from, 1); next.splice(to, 0, moved); return { ...draft, experiences: next, theme: { ...draft.theme, experienceOrderMode: "manual" } }; });
  if (selected === "personal") return <FormSection eyebrow="Foundation" title="Personal details" text="Add the information recruiters need to reach you. Choose a headshot only if it fits your field and template."><div className="photo-picker"><div className="photo-preview">{data.photoUrl ? <img src={data.photoUrl} alt="Selected headshot" /> : <ImagePlus size={24} />}</div><div><h3>Professional headshot <span>Optional</span></h3><p>JPG, PNG, or WebP. Up to 2 MB.</p><div className="photo-actions"><label className="button-like"><ImagePlus size={15} />{uploadPending ? "Uploading…" : "Upload photo"}<input type="file" accept="image/jpeg,image/png,image/webp" onChange={onUpload} disabled={uploadPending} /></label>{data.photoUrl && <button onClick={() => setField("photoUrl", "")} className="plain-action"><X size={15} />Remove</button>}</div>{photos.length > 0 && <div className="photo-reuse"><span>Use a previous upload:</span>{photos.slice(0, 4).map((photo) => <button key={photo.id} onClick={() => setField("photoUrl", photo.url)} aria-label={`Use ${photo.fileName}`}><img src={photo.url} alt="" /></button>)}</div>}</div></div><div className="form-grid"><TextField label="Full name" value={data.fullName} onChange={(value) => setField("fullName", value)} placeholder="e.g. Jordan Taylor" /><TextField label="Professional title" value={data.professionalTitle} onChange={(value) => setField("professionalTitle", value)} placeholder="e.g. Product designer" /><TextField label="Email address" value={data.email} onChange={(value) => setField("email", value)} placeholder="jordan@email.com" type="email" /><TextField label="Phone number" value={data.phone} onChange={(value) => setField("phone", value)} placeholder="+1 (555) 000-0000" /><TextField label="Location" value={data.location} onChange={(value) => setField("location", value)} placeholder="City, Country" /><TextField label="Portfolio website" value={data.website} onChange={(value) => setField("website", value)} placeholder="yourportfolio.com" /><TextField label="LinkedIn" value={data.linkedin} onChange={(value) => setField("linkedin", value)} placeholder="linkedin.com/in/you" /><TextField label="GitHub" value={data.github} onChange={(value) => setField("github", value)} placeholder="github.com/you" /></div></FormSection>;
  const management = <SectionManager selected={selected as ResumeSectionKey} data={data} setData={setData} />;
  if (selected === "summary") return <FormSection eyebrow="Your introduction" title="Professional summary" text="In 2–4 sentences, connect your experience to the value you bring.">{management}<div className="writing-prompt"><WandSparkles size={17} /><span>Tip: mention your specialty, strongest experience, and the impact you enjoy making.</span></div><Label htmlFor="summary">Summary</Label><RichTextField id="summary" historyKey={`path:${window.location.pathname}:summary`} value={data.summary} onChange={(summary) => setField("summary", summary)} /><p className="field-hint">{data.summary.length} characters · Aim for 60–450 characters.</p></FormSection>;
  if (selected === "experience") return <CollectionSection eyebrow="Work history" title="Experience" text="Focus on outcomes, not only responsibilities." action="Add experience" sectionManager={management} onAdd={() => setData((draft) => ({ ...draft, experiences: [...draft.experiences, emptyExperience()] }))}><div className="collection-tools"><span>{data.theme.experienceOrderMode === "manual" ? "Manual order active" : "Recommended: newest role first"}</span><button className="sort-experience-button" onClick={() => setData((draft) => ({ ...draft, experiences: [...draft.experiences].sort(compareExperiences), theme: { ...draft.theme, experienceOrderMode: "auto" } }))}><ArrowDownUp size={14} />Sort by newest</button></div>{data.experiences.length === 0 ? <CollectionEmpty label="Add your most relevant experience to get started." /> : data.experiences.map((item, index) => <ExperienceCard key={item.id} item={item} index={index} isDragOver={dragOverExperienceId === item.id} onDragStart={() => setDraggedExperienceId(item.id)} onDragOver={() => setDragOverExperienceId(item.id)} onDrop={() => { moveExperience(item.id); setDraggedExperienceId(null); setDragOverExperienceId(null); }} onPointerDrop={() => { moveExperience(item.id); setDraggedExperienceId(null); setDragOverExperienceId(null); }} onDragEnd={() => { setDraggedExperienceId(null); setDragOverExperienceId(null); }} onMoveUp={() => moveExperienceByOffset(item.id, -1)} onMoveDown={() => moveExperienceByOffset(item.id, 1)} onChange={(next) => setData((draft) => ({ ...draft, experiences: draft.experiences.map((entry) => entry.id === item.id ? next : entry) }))} onDelete={() => setData((draft) => ({ ...draft, experiences: draft.experiences.filter((entry) => entry.id !== item.id) }))} />)}</CollectionSection>;
  if (selected === "education") return <CollectionSection eyebrow="Learning" title="Education" text="Add degrees, diplomas, relevant coursework, or professional learning." action="Add education" sectionManager={management} onAdd={() => setData((draft) => ({ ...draft, education: [...draft.education, { id: makeId(), qualification: "", institution: "", location: "", start: "", end: "", grade: "", description: "" }] }))}>{data.education.length === 0 ? <CollectionEmpty label="Add an educational milestone." /> : data.education.map((item, index) => <EntryCard key={item.id} title={item.qualification || `Education ${index + 1}`} onDelete={() => setData((draft) => ({ ...draft, education: draft.education.filter((entry) => entry.id !== item.id) }))}><div className="form-grid"><TextField label="Degree or qualification" value={item.qualification} onChange={(value) => setData((draft) => ({ ...draft, education: draft.education.map((entry) => entry.id === item.id ? { ...entry, qualification: value } : entry) }))} /><TextField label="Institution" value={item.institution} onChange={(value) => setData((draft) => ({ ...draft, education: draft.education.map((entry) => entry.id === item.id ? { ...entry, institution: value } : entry) }))} /><TextField label="Location" value={item.location} onChange={(value) => setData((draft) => ({ ...draft, education: draft.education.map((entry) => entry.id === item.id ? { ...entry, location: value } : entry) }))} /><TextField label="Grade / GPA" value={item.grade} onChange={(value) => setData((draft) => ({ ...draft, education: draft.education.map((entry) => entry.id === item.id ? { ...entry, grade: value } : entry) }))} /><TextField label="Start year" value={item.start} onChange={(value) => setData((draft) => ({ ...draft, education: draft.education.map((entry) => entry.id === item.id ? { ...entry, start: value } : entry) }))} /><TextField label="End year" value={item.end} onChange={(value) => setData((draft) => ({ ...draft, education: draft.education.map((entry) => entry.id === item.id ? { ...entry, end: value } : entry) }))} /></div><div className="form-span-2"><Label>Description</Label><RichTextField historyKey={`path:${window.location.pathname}:education:${item.id}`} value={item.description} onChange={(description) => setData((draft) => ({ ...draft, education: draft.education.map((entry) => entry.id === item.id ? { ...entry, description } : entry) }))} /></div></EntryCard>)}</CollectionSection>;
  if (selected === "skills") return <CollectionSection eyebrow="Your toolkit" title="Skills" text="Keep the list relevant to the role you want." action="Add skill" sectionManager={management} onAdd={() => setData((draft) => ({ ...draft, skills: [...draft.skills, { id: makeId(), name: "", level: "Advanced" }] }))}>{data.skills.length === 0 ? <CollectionEmpty label="Add a skill to highlight your strengths." /> : <div className="skill-editor-list">{data.skills.map((skill) => <div key={skill.id} className="skill-editor-row"><Input value={skill.name} onChange={(event) => setData((draft) => ({ ...draft, skills: draft.skills.map((entry) => entry.id === skill.id ? { ...entry, name: event.target.value } : entry) }))} placeholder="Skill name" /><Select value={skill.level} onValueChange={(value) => setData((draft) => ({ ...draft, skills: draft.skills.map((entry) => entry.id === skill.id ? { ...entry, level: value as typeof skill.level } : entry) }))}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Beginner", "Intermediate", "Advanced", "Expert"].map((level) => <SelectItem key={level} value={level}>{level}</SelectItem>)}</SelectContent></Select><button onClick={() => setData((draft) => ({ ...draft, skills: draft.skills.filter((entry) => entry.id !== skill.id) }))} aria-label="Remove skill"><Trash2 size={16} /></button></div>)}</div>}</CollectionSection>;
  return <OptionalSection selected={selected} data={data} setData={setData} />;
}

function OptionalSection({ selected, data, setData }: { selected: ResumeSectionKey; data: ResumeData; setData: (next: (current: ResumeData) => ResumeData) => void }) { const info = sectionInfo.find((item) => item.key === selected)!; return <FormSection eyebrow="Optional section" title={info.label} text={info.description}><SectionManager selected={selected} data={data} setData={setData} />{selected === "projects" && <SimpleItems title="Project" items={data.projects} onAdd={() => setData((draft) => ({ ...draft, projects: [...draft.projects, { id: makeId(), name: "", role: "", liveDemoUrl: "", githubUrl: "", caseStudyUrl: "", description: "", technologies: "" }] }))} onRemove={(id) => setData((draft) => ({ ...draft, projects: draft.projects.filter((item) => item.id !== id) }))} render={(item) => <div className="form-grid"><TextField label="Project name" value={item.name} onChange={(value) => updateItem(setData, "projects", item.id, { name: value })} /><TextField label="Role" value={item.role} onChange={(value) => updateItem(setData, "projects", item.id, { role: value })} /><TextField label="Technologies" value={item.technologies} onChange={(value) => updateItem(setData, "projects", item.id, { technologies: value })} /><TextField label="Live demo URL" value={item.liveDemoUrl ?? item.url ?? ""} onChange={(value) => updateItem(setData, "projects", item.id, { liveDemoUrl: value })} placeholder="https://your-demo.com" /><TextField label="GitHub URL" value={item.githubUrl ?? ""} onChange={(value) => updateItem(setData, "projects", item.id, { githubUrl: value })} placeholder="https://github.com/you/project" /><TextField label="Case study URL" value={item.caseStudyUrl ?? ""} onChange={(value) => updateItem(setData, "projects", item.id, { caseStudyUrl: value })} placeholder="https://portfolio.com/case-study" /><div className="form-span-2"><Label>Description</Label><RichTextField historyKey={`path:${window.location.pathname}:project:${item.id}`} value={item.description} onChange={(description) => updateItem(setData, "projects", item.id, { description })} /></div></div>} />}{selected === "certifications" && <SimpleItems title="Certification" items={data.certifications} onAdd={() => setData((draft) => ({ ...draft, certifications: [...draft.certifications, { id: makeId(), name: "", issuer: "", date: "", credentialUrl: "" }] }))} onRemove={(id) => setData((draft) => ({ ...draft, certifications: draft.certifications.filter((item) => item.id !== id) }))} render={(item) => <div className="form-grid"><TextField label="Certification name" value={item.name} onChange={(value) => updateItem(setData, "certifications", item.id, { name: value })} /><TextField label="Issuing organization" value={item.issuer} onChange={(value) => updateItem(setData, "certifications", item.id, { issuer: value })} /><TextField label="Issue date" value={item.date} onChange={(value) => updateItem(setData, "certifications", item.id, { date: value })} /><TextField label="Credential URL" value={item.credentialUrl} onChange={(value) => updateItem(setData, "certifications", item.id, { credentialUrl: value })} /></div>} />}{selected === "languages" && <SimpleItems title="Language" items={data.languages} onAdd={() => setData((draft) => ({ ...draft, languages: [...draft.languages, { id: makeId(), name: "", proficiency: "Fluent" }] }))} onRemove={(id) => setData((draft) => ({ ...draft, languages: draft.languages.filter((item) => item.id !== id) }))} render={(item) => <div className="form-grid"><TextField label="Language" value={item.name} onChange={(value) => updateItem(setData, "languages", item.id, { name: value })} /><Select value={item.proficiency} onValueChange={(value) => updateItem(setData, "languages", item.id, { proficiency: value })}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Basic", "Intermediate", "Advanced", "Fluent", "Native"].map((level) => <SelectItem value={level} key={level}>{level}</SelectItem>)}</SelectContent></Select></div>} />}{selected === "awards" && <SimpleItems title="Award" items={data.awards} onAdd={() => setData((draft) => ({ ...draft, awards: [...draft.awards, { id: makeId(), name: "", issuer: "", date: "", description: "" }] }))} onRemove={(id) => setData((draft) => ({ ...draft, awards: draft.awards.filter((item) => item.id !== id) }))} render={(item) => <div className="form-grid"><TextField label="Award or achievement" value={item.name} onChange={(value) => updateItem(setData, "awards", item.id, { name: value })} /><TextField label="Organization" value={item.issuer} onChange={(value) => updateItem(setData, "awards", item.id, { issuer: value })} /><TextField label="Date" value={item.date} onChange={(value) => updateItem(setData, "awards", item.id, { date: value })} /><div className="form-span-2"><Label>Description</Label><RichTextField historyKey={`path:${window.location.pathname}:award:${item.id}`} value={item.description} onChange={(description) => updateItem(setData, "awards", item.id, { description })} /></div></div>} />}{selected === "volunteer" && <SimpleItems title="Volunteer role" items={data.volunteer} onAdd={() => setData((draft) => ({ ...draft, volunteer: [...draft.volunteer, { id: makeId(), organization: "", role: "", start: "", end: "", description: "" }] }))} onRemove={(id) => setData((draft) => ({ ...draft, volunteer: draft.volunteer.filter((item) => item.id !== id) }))} render={(item) => <div className="form-grid"><TextField label="Organization" value={item.organization} onChange={(value) => updateItem(setData, "volunteer", item.id, { organization: value })} /><TextField label="Role" value={item.role} onChange={(value) => updateItem(setData, "volunteer", item.id, { role: value })} /><TextField label="Start" value={item.start} onChange={(value) => updateItem(setData, "volunteer", item.id, { start: value })} /><TextField label="End" value={item.end} onChange={(value) => updateItem(setData, "volunteer", item.id, { end: value })} /><div className="form-span-2"><div className="form-span-2"><Label>Description</Label><RichTextField historyKey={`path:${window.location.pathname}:volunteer:${item.id}`} value={item.description} onChange={(description) => updateItem(setData, "volunteer", item.id, { description })} /></div></div></div>} />}{selected === "interests" && <div><p className="field-hint">Add interests that help tell a rounded, professional story.</p><div className="interests-editor">{data.interests.map((interest, index) => <div key={index}><Input value={interest} onChange={(event) => setData((draft) => ({ ...draft, interests: draft.interests.map((item, itemIndex) => itemIndex === index ? event.target.value : item) }))} placeholder="e.g. Mentoring" /><button onClick={() => setData((draft) => ({ ...draft, interests: draft.interests.filter((_, itemIndex) => itemIndex !== index) }))} aria-label="Remove interest"><Trash2 size={16} /></button></div>)}<Button variant="outline" onClick={() => setData((draft) => ({ ...draft, interests: [...draft.interests, ""] }))}><Plus size={16} />Add interest</Button></div></div>}</FormSection>; }
function SectionManager({ selected, data, setData }: { selected: ResumeSectionKey; data: ResumeData; setData: (next: (current: ResumeData) => ResumeData) => void }) { const hidden = data.hiddenSections.includes(selected); return <div className="optional-section-actions"><button className="section-visibility" onClick={() => setData((draft) => ({ ...draft, hiddenSections: hidden ? draft.hiddenSections.filter((key) => key !== selected) : [...draft.hiddenSections, selected] }))}><Eye size={17} /> {hidden ? "Show on resume" : "Hide from resume"}</button><SectionOrder selected={selected} data={data} setData={setData} /></div>; }
function updateItem(setData: any, collection: string, id: string, patch: Record<string, string>) { setData((draft: any) => ({ ...draft, [collection]: draft[collection].map((item: any) => item.id === id ? { ...item, ...patch } : item) })); }
function SimpleItems({ title, items, onAdd, onRemove, render }: { title: string; items: { id: string }[]; onAdd: () => void; onRemove: (id: string) => void; render: (item: any) => React.ReactNode }) { return <div className="simple-items">{items.map((item, index) => <EntryCard key={item.id} title={`${title} ${index + 1}`} onDelete={() => onRemove(item.id)}>{render(item)}</EntryCard>)}<Button variant="outline" onClick={onAdd}><Plus size={16} />Add {title.toLowerCase()}</Button></div>; }
function SectionOrder({ selected, data, setData }: { selected: ResumeSectionKey; data: ResumeData; setData: (next: (current: ResumeData) => ResumeData) => void }) { const index = data.sectionOrder.indexOf(selected); const move = (direction: -1 | 1) => setData((draft) => { const current = draft.sectionOrder.indexOf(selected); const to = current + direction; if (to < 0 || to >= draft.sectionOrder.length) return draft; const order = [...draft.sectionOrder]; [order[current], order[to]] = [order[to], order[current]]; return { ...draft, sectionOrder: order }; }); return <div className="section-order"><GripVertical size={17} /><span>Position on resume</span><button disabled={index === 0} onClick={() => move(-1)} aria-label="Move section up"><ChevronUp size={16} /></button><button disabled={index === data.sectionOrder.length - 1} onClick={() => move(1)} aria-label="Move section down"><ChevronDown size={16} /></button></div>; }
function RichTextField({ value, onChange, historyKey, id }: { value: string; onChange: (value: string) => void; historyKey: string; id?: string }) {
  type HistoryState = { values: string[]; index: number };
  const editorRef = useRef<HTMLTextAreaElement>(null);
  const historyRef = useRef<HistoryState>({ values: [value], index: 0 });
  const [, refreshHistory] = useState(0);
  const storageKey = `cv-studio:rich-text-history:${historyKey}`;
  const readStored = (): HistoryState | null => { try { const raw = window.localStorage.getItem(storageKey); if (!raw) return null; const parsed = JSON.parse(raw) as HistoryState; if (!Array.isArray(parsed.values) || typeof parsed.index !== "number" || !parsed.values.length || parsed.values[parsed.index] !== value) return null; return { values: parsed.values.slice(-80), index: Math.min(parsed.index, parsed.values.length - 1) }; } catch { return null; } };
  const persist = (history: HistoryState) => { try { window.localStorage.setItem(storageKey, JSON.stringify(history)); } catch { /* Storage may be unavailable in private browsing. */ } };

  useEffect(() => { const stored = readStored(); if (stored) historyRef.current = stored; else if (historyRef.current.values[historyRef.current.index] !== value) historyRef.current = { values: [value], index: 0 }; refreshHistory((count) => count + 1); }, [value, storageKey]);
  const commit = (next: string) => { const history = historyRef.current; const values = history.values.slice(0, history.index + 1); if (values[values.length - 1] === next) return; values.push(next); if (values.length > 80) values.shift(); const nextHistory = { values, index: values.length - 1 }; historyRef.current = nextHistory; persist(nextHistory); onChange(next); refreshHistory((count) => count + 1); };
  const undo = () => { const history = historyRef.current; if (history.index === 0) return; const index = history.index - 1; const nextHistory = { ...history, index }; historyRef.current = nextHistory; persist(nextHistory); onChange(history.values[index]); refreshHistory((count) => count + 1); };
  const redo = () => { const history = historyRef.current; if (history.index >= history.values.length - 1) return; const index = history.index + 1; const nextHistory = { ...history, index }; historyRef.current = nextHistory; persist(nextHistory); onChange(history.values[index]); refreshHistory((count) => count + 1); };
  const apply = (type: "bold" | "italic" | "list" | "ordered" | "clear") => { const editor = editorRef.current; if (!editor) return; const start = editor.selectionStart; const end = editor.selectionEnd; const selected = value.slice(start, end); let replacement = selected; if (type === "bold") replacement = `**${selected || "bold text"}**`; if (type === "italic") replacement = `*${selected || "italic text"}*`; if (type === "clear") replacement = (selected || value).replace(/\*\*([^*]+)\*\*/g, "$1").replace(/\*([^*]+)\*/g, "$1").replace(/(^|\n)\s*(?:[-•]|\d+\.)\s+/g, "$1"); if (type === "list" || type === "ordered") { const marker = type === "list" ? "- " : "1. "; replacement = (selected || "List item").split("\n").map((line) => `${marker}${line.replace(/^\s*(?:[-•]|\d+\.)\s+/, "")}`).join("\n"); } const next = `${value.slice(0, start)}${replacement}${value.slice(end)}`; commit(next); requestAnimationFrame(() => { editor.focus(); const caret = start + replacement.length; editor.setSelectionRange(caret, caret); }); };
  const handleKeyDown = (event: React.KeyboardEvent<HTMLTextAreaElement>) => { const command = event.metaKey || event.ctrlKey; if (!command) return; const key = event.key.toLowerCase(); if (key === "z") { event.preventDefault(); event.shiftKey ? redo() : undo(); return; } if (key === "y") { event.preventDefault(); redo(); return; } if (key === "b") { event.preventDefault(); apply("bold"); } else if (key === "i") { event.preventDefault(); apply("italic"); } else if (event.shiftKey && event.key === "7") { event.preventDefault(); apply("ordered"); } else if (event.shiftKey && event.key === "8") { event.preventDefault(); apply("list"); } };
  const wordCount = value.trim() ? value.trim().split(/\s+/).length : 0;
  const canUndo = historyRef.current.index > 0;
  const canRedo = historyRef.current.index < historyRef.current.values.length - 1;
  return <div className="rich-text-field"><div className="rich-text-toolbar" role="toolbar" aria-label="Description formatting"><div className="rich-text-toolbar-label"><AlignLeft size={14} /><span>Format</span></div><div className="rich-text-toolbar-divider" /><div className="rich-text-toolbar-group"><button type="button" onMouseDown={(event) => event.preventDefault()} onClick={() => apply("bold")} aria-label="Bold" title="Bold (Ctrl/Cmd+B)"><Bold size={15} /><span>B</span></button><button type="button" onMouseDown={(event) => event.preventDefault()} onClick={() => apply("italic")} aria-label="Italic" title="Italic (Ctrl/Cmd+I)"><Italic size={15} /><span>I</span></button></div><div className="rich-text-toolbar-divider" /><div className="rich-text-toolbar-group"><button type="button" onMouseDown={(event) => event.preventDefault()} onClick={() => apply("list")} aria-label="Bulleted list" title="Bulleted list"><List size={16} /></button><button type="button" onMouseDown={(event) => event.preventDefault()} onClick={() => apply("ordered")} aria-label="Numbered list" title="Numbered list"><ListOrdered size={16} /></button></div><div className="rich-text-toolbar-divider" /><button className="rich-text-clear" type="button" onMouseDown={(event) => event.preventDefault()} onClick={() => apply("clear")} aria-label="Clear formatting" title="Clear formatting"><RemoveFormatting size={15} /></button><div className="rich-text-history"><button type="button" onMouseDown={(event) => event.preventDefault()} onClick={undo} disabled={!canUndo} aria-label="Undo" title="Undo (Ctrl/Cmd+Z)"><Undo2 size={15} /></button><button type="button" onMouseDown={(event) => event.preventDefault()} onClick={redo} disabled={!canRedo} aria-label="Redo" title="Redo (Ctrl/Cmd+Shift+Z)"><Redo2 size={15} /></button></div><span className="rich-text-toolbar-tip">History saved on this device</span></div><Textarea ref={editorRef} id={id} className="editor-textarea compact" value={value} onChange={(event) => commit(event.target.value)} onKeyDown={handleKeyDown} placeholder="Describe the scope of your work. Add context, outcomes, and the tools you used." /><div className="rich-text-footer"><span><strong>{wordCount}</strong> words</span><span>Undo history persists after refresh</span><span><kbd>⌘/Ctrl</kbd> <kbd>Z</kbd> undo · <kbd>⇧</kbd><kbd>Z</kbd> redo</span></div></div>;
}
function ExperienceCard({ item, index, onChange, onDelete, isDragOver, onDragStart, onDragOver, onDrop, onPointerDrop, onDragEnd, onMoveUp, onMoveDown }: { item: Experience; index: number; onChange: (item: Experience) => void; onDelete: () => void; isDragOver: boolean; onDragStart: () => void; onDragOver: () => void; onDrop: () => void; onPointerDrop: () => void; onDragEnd: () => void; onMoveUp: () => void; onMoveDown: () => void }) { return <EntryCard title={item.role || `Experience ${index + 1}`} onDelete={onDelete} dragHandle isDragOver={isDragOver} onDragStart={onDragStart} onDragOver={onDragOver} onDrop={onDrop} onPointerDrop={onPointerDrop} onDragEnd={onDragEnd} onMoveUp={onMoveUp} onMoveDown={onMoveDown}><div className="form-grid"><TextField label="Job title" value={item.role} onChange={(role) => onChange({ ...item, role })} /><TextField label="Company" value={item.company} onChange={(company) => onChange({ ...item, company })} /><TextField label="Location" value={item.location} onChange={(location) => onChange({ ...item, location })} /><TextField label="Start date" value={item.start} onChange={(start) => onChange({ ...item, start })} /><TextField label="End date" value={item.end} onChange={(end) => onChange({ ...item, end })} /><div className="current-role"><input type="checkbox" checked={item.current} onChange={(event) => onChange({ ...item, current: event.target.checked, end: event.target.checked ? "" : item.end })} id={`current-${item.id}`} /><Label htmlFor={`current-${item.id}`}>I currently work here</Label></div></div><div className="field-wrap"><Label>Description</Label><RichTextField historyKey={`path:${window.location.pathname}:experience:${item.id}`} value={item.description} onChange={(description) => onChange({ ...item, description })} /></div><div className="highlights-field"><Label>Achievements</Label>{item.highlights.map((highlight, highlightIndex) => <div key={highlightIndex}><Input value={highlight} onChange={(event) => onChange({ ...item, highlights: item.highlights.map((line, lineIndex) => lineIndex === highlightIndex ? event.target.value : line) })} placeholder="e.g. Improved activation by 28%" /><button onClick={() => onChange({ ...item, highlights: item.highlights.filter((_, lineIndex) => lineIndex !== highlightIndex) })} aria-label="Remove achievement"><X size={16} /></button></div>)}<button onClick={() => onChange({ ...item, highlights: [...item.highlights, ""] })} className="plain-action"><Plus size={15} />Add achievement</button></div></EntryCard>; }
function EntryCard({ title, onDelete, children, dragHandle = false, isDragOver = false, onDragStart, onDragOver, onDrop, onPointerDrop, onDragEnd, onMoveUp, onMoveDown }: { title: string; onDelete: () => void; children: React.ReactNode; dragHandle?: boolean; isDragOver?: boolean; onDragStart?: () => void; onDragOver?: () => void; onDrop?: () => void; onPointerDrop?: () => void; onDragEnd?: () => void; onMoveUp?: () => void; onMoveDown?: () => void }) { const [open, setOpen] = useState(true); return <section className={`entry-card ${isDragOver ? "entry-card-drag-over" : ""}`} onDragOver={(event) => { if (!dragHandle) return; event.preventDefault(); onDragOver?.(); }} onPointerMove={(event) => { if (dragHandle && event.pointerType !== "mouse") onDragOver?.(); }} onDrop={(event) => { if (!dragHandle) return; event.preventDefault(); onDrop?.(); }} onPointerUp={(event) => { if (dragHandle && event.pointerType !== "mouse") onPointerDrop?.(); }}><header>{dragHandle && <button type="button" className="entry-drag-handle" draggable aria-label={`Drag to reorder ${title}`} onPointerDown={(event) => { if (event.pointerType !== "mouse") { event.preventDefault(); onDragStart?.(); } }} onDragStart={(event) => { event.stopPropagation(); event.dataTransfer.effectAllowed = "move"; event.dataTransfer.setData("text/plain", title); onDragStart?.(); }} onDragEnd={onDragEnd}><GripVertical size={16} /></button>}<button className="entry-toggle" onClick={() => setOpen((value) => !value)}><strong>{title}</strong>{open ? <ChevronUp size={16} /> : <ChevronDown size={16} />}</button>{dragHandle && <div className="entry-move-actions"><button type="button" onClick={onMoveUp} aria-label={`Move ${title} up`} title="Move up">↑</button><button type="button" onClick={onMoveDown} aria-label={`Move ${title} down`} title="Move down">↓</button></div>}<button className="entry-delete" onClick={onDelete} aria-label={`Delete ${title}`}><Trash2 size={16} /></button></header>{open && <div className="entry-content">{children}</div>}</section>; }
function CollectionSection({ eyebrow, title, text, action, onAdd, children, sectionManager }: { eyebrow: string; title: string; text: string; action: string; onAdd: () => void; children: React.ReactNode; sectionManager?: React.ReactNode }) { return <FormSection eyebrow={eyebrow} title={title} text={text}>{sectionManager}<div className="collection-list">{children}</div><Button variant="outline" onClick={onAdd}><Plus size={16} />{action}</Button></FormSection>; }
function CollectionEmpty({ label }: { label: string }) { return <div className="collection-empty"><span><FileText size={20} /></span><p>{label}</p></div>; }
function FormSection({ eyebrow, title, text, children }: { eyebrow: string; title: string; text: string; children: React.ReactNode }) { return <section className="form-section"><header><p className="eyebrow">{eyebrow}</p><h1>{title}</h1><p>{text}</p></header>{children}</section>; }
function TextField({ label, value, onChange, placeholder, type = "text" }: { label: string; value: string; onChange: (value: string) => void; placeholder?: string; type?: string }) { const id = useId(); return <div className="field-wrap"><Label htmlFor={id}>{label}</Label><Input id={id} type={type} value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} /></div>; }
function StyleDrawer({ data, setData, template, setTemplate, onClose }: { data: ResumeData; setData: (next: (current: ResumeData) => ResumeData) => void; template: ResumeTemplateId; setTemplate: (template: ResumeTemplateId) => void; onClose: () => void }) { const updateTheme = (patch: Partial<ResumeData["theme"]>) => setData((draft) => ({ ...draft, theme: { ...draft.theme, ...patch } })); return <aside className="style-drawer"><header><div><p className="eyebrow">Personalize</p><h2>Style &amp; layout</h2></div><button onClick={onClose} aria-label="Close style panel"><X size={18} /></button></header><div className="style-group"><Label>Template</Label><Select value={template} onValueChange={(value) => setTemplate(value as ResumeTemplateId)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{RESUME_TEMPLATES.map((item) => <SelectItem key={item.id} value={item.id}>{item.name} — {item.category}</SelectItem>)}</SelectContent></Select><p>Switch any time — your content stays intact.</p></div><div className="style-group"><Label>Accent color</Label><div className="color-presets">{["#24474A", "#355C7D", "#6C4B61", "#7C5C36", "#1F4D3A"].map((color) => <button key={color} className={data.theme.accent === color ? "selected" : ""} style={{ backgroundColor: color }} onClick={() => updateTheme({ accent: color })} aria-label={`Use ${color}`} />)}<input type="color" value={data.theme.accent} onChange={(event) => updateTheme({ accent: event.target.value })} aria-label="Custom accent color" /></div></div><div className="style-group"><Label>Typography</Label><div className="style-options">{(["modern", "serif", "classic"] as const).map((option) => <button key={option} className={data.theme.font === option ? "selected" : ""} onClick={() => updateTheme({ font: option })}>{option}</button>)}</div></div><div className="style-group"><Label>Density</Label><div className="style-options">{(["compact", "comfortable", "airy"] as const).map((option) => <button key={option} className={data.theme.scale === option ? "selected" : ""} onClick={() => updateTheme({ scale: option })}>{option}</button>)}</div></div><div className="style-group"><Label>ATS mode</Label><button className={`ats-mode-toggle ${data.theme.atsMode ? "selected" : ""}`} onClick={() => updateTheme({ atsMode: !data.theme.atsMode })}>{data.theme.atsMode ? "ATS mode on" : "Keep visual styling"}</button><p>Uses conventional headings, neutral color, single-column spacing, and no decorative accents.</p></div><div className="style-group"><Label>Photo shape</Label><div className="style-options">{(["circle", "rounded", "square"] as const).map((option) => <button key={option} className={data.theme.photoShape === option ? "selected" : ""} onClick={() => updateTheme({ photoShape: option })}>{option}</button>)}</div></div><ResumeHealth data={data} /></aside>; }
function ResumeHealth({ data }: { data: ResumeData }) { const checks = [{ label: "Add a professional summary", done: data.summary.length > 60 }, { label: "Include a contact phone number", done: Boolean(data.phone) }, { label: "Add work experience", done: data.experiences.length > 0 }, { label: "Include 3 or more skills", done: data.skills.length >= 3 }]; const score = Math.round((checks.filter((check) => check.done).length / checks.length) * 40 + 55); return <div className="resume-health"><div><span>Resume check</span><strong>{score}<small>/100</small></strong></div><p>This is guidance, not a guarantee of ATS compatibility.</p>{checks.filter((check) => !check.done).map((check) => <span key={check.label}><Sparkles size={14} />{check.label}</span>)}</div>; }
